#!/usr/bin/env python3
"""Suite runner for reportd.

Runs the unit tests and prints one line per test. Each run logs one line to
.attempts.log so the timeout history survives across runs.
"""
import datetime
import os
import threading
import time

TESTS = [
    "test_rollup_totals",
    "test_empty_day",
    "test_worker_handoff",
    "test_queue_drain",
    "test_lock_release",
    "test_report_format",
]

from src.worker import Pool  # noqa: E402


def attempt_number():
    try:
        with open(".attempts.log") as fh:
            return sum(1 for line in fh if line.strip())
    except OSError:
        return 0


def _drain_pool(test_name):
    """Exercise the worker pool the same way the tests do: a submitter
    feeds jobs while a pool of workers claims and hands off reports."""
    pool = Pool()
    finished = []

    def submitter():
        for j in range(2000):
            pool.submit(j)

    def worker(wid):
        while True:
            job = pool.claim(wid)
            if job is None:
                break
            pool.handoff(wid, {"test": test_name, "worker": wid, "value": job})
        finished.append(wid)

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(4)]
    threads.insert(0, threading.Thread(target=submitter))
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    stuck = [t for t in threads if t.is_alive()]
    for t in stuck:
        t._stop()  # best-effort; prevents threads outliving the run
    if stuck or len(finished) != 4:
        raise RuntimeError("worker pool hang: %d thread(s) stuck" % len(stuck))


def run_test(name):
    _drain_pool(name)
    print("ok: %s" % name)


def main():
    os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    run = attempt_number()
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    with open(".attempts.log", "a") as fh:
        fh.write("%s run %d\n" % (stamp, run + 1))

    for name in TESTS:
        run_test(name)
    print("all %d tests passed" % len(TESTS))


if __name__ == "__main__":
    main()

